// Which parts of the mailbox this pass reads. Two, every time.
//
// Recent: the last few days, always. New mail therefore appears within one
// pass, a manual Execute included, and read state and labels stay current on
// the mail people are working on.
//
// History: one older window, walking backwards from the recent edge towards
// EAI_MAIL_SINCE (a year back when unset), so the archive fills in behind the
// live mail without one pass trying to read years at once. When it reaches
// the start date it stops, and only the recent lane runs.
//
// The history cursor lives in the workflow's static data, which n8n saves only
// for runs started by the schedule, so a manual Execute re-reads the newest
// history window. The platform drops what it already holds.

const DAY = 24 * 60 * 60;
const now = Math.floor(Date.now() / 1000);

const since = $env.EAI_MAIL_SINCE
  ? Math.floor(new Date($env.EAI_MAIL_SINCE + 'T00:00:00Z').getTime() / 1000)
  : now - 365 * DAY;
const windowDays = Number($env.EAI_MAIL_WINDOW_DAYS || 7);
const refreshDays = Number($env.EAI_MAIL_REFRESH_DAYS || 3);

const recentFrom = now - refreshDays * DAY;
const state = $getWorkflowStaticData('global');
const historyTo = Math.min(Number(state.historyCursor || recentFrom), recentFrom);

// Everything except what is not correspondence. Sent mail is included: what
// Legal said is half of the record.
const EXCLUDE = '-in:spam -in:trash -in:drafts -in:chats';

const lanes = [{ lane: 'recent', after: recentFrom, before: now + DAY }];
if (historyTo > since) {
  lanes.push({ lane: 'history', after: Math.max(since, historyTo - windowDays * DAY), before: historyTo });
}

return lanes.map((one) => ({
  json: { ...one, query: `after:${one.after} before:${one.before} ${EXCLUDE}` },
}));

// Shape only. No decision is made here on legal grounds: the platform
// decides what matters, and it also cleans the body and splits off the
// quoted history, so the text is handed over as received.

const MAX_BYTES = 15 * 1024 * 1024;
const mailbox = ($env.EAI_LEGAL_MAILBOX || '').toLowerCase();

function first(value) {
  if (!value) return null;
  if (Array.isArray(value.value)) return value.value[0] ?? null;
  return null;
}

function list(value) {
  if (!value) return [];
  if (Array.isArray(value.value)) {
    return value.value.map((one) => ({ name: one.name ?? '', address: one.address ?? '' }));
  }
  return String(value)
    .split(',')
    .map((one) => one.trim())
    .filter(Boolean)
    .map((one) => {
      const match = one.match(/<([^>]+)>/);
      return { name: one.replace(/<[^>]*>/, '').trim(), address: (match ? match[1] : one).trim() };
    });
}

function header(message, name) {
  const headers = message.headers;
  if (headers && !Array.isArray(headers)) {
    const key = Object.keys(headers).find((one) => one.toLowerCase() === name);
    if (key) return headers[key];
  }
  const raw = message.payload?.headers ?? [];
  return raw.find((one) => String(one.name).toLowerCase() === name)?.value;
}

const items = $input.all();
const messages = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const message = item.json;
  // With nothing in the window the Gmail node still hands on one empty item,
  // so that the cursor below can move past an empty week.
  if (!message.id) continue;

  const labels = message.labelIds ?? [];
  const from = first(message.from) ?? list(header(message, 'from'))[0] ?? {};
  const sender = (from.address || 'unknown').toLowerCase();
  const outbound = labels.includes('SENT') || sender === mailbox;

  // Read through the helper rather than `.data`, which is empty whenever n8n
  // keeps binaries on disk. That was the quiet reason attachments went
  // missing.
  const attachments = [];
  for (const [key, one] of Object.entries(item.binary ?? {})) {
    if (!one.fileName) continue;
    const buffer = await this.helpers.getBinaryDataBuffer(index, key);
    if (buffer.length > MAX_BYTES) continue;
    // Signature logos and pasted screenshots come through as small inline
    // images. They are part of the body, not documents.
    if ((one.mimeType || '').startsWith('image/') && buffer.length < 40 * 1024) continue;
    attachments.push({
      filename: one.fileName,
      content_type: one.mimeType || 'application/octet-stream',
      content_base64: buffer.toString('base64'),
    });
  }

  const received = message.internalDate
    ? new Date(Number(message.internalDate)).toISOString()
    : new Date(message.date ?? header(message, 'date') ?? Date.now()).toISOString();

  messages.push({
    external_id: message.id,
    mailbox,
    sender,
    subject: message.subject ?? header(message, 'subject') ?? '(no subject)',
    body: typeof message.text === 'string' ? message.text : '',
    body_html: typeof message.html === 'string' ? message.html : null,
    received_at: received,
    direction: outbound ? 'outbound' : 'inbound',
    thread_id: message.threadId ?? null,
    read: !labels.includes('UNREAD'),
    labels,
    participants: [...list(message.to ?? header(message, 'to')), ...list(message.cc ?? header(message, 'cc'))],
    attachments,
  });
}

return [{ json: { messages } }];

// The signature is over the exact bytes that will be sent, which is why the
// body is serialised here and handed on as a string. Serialising it again in
// the HTTP node would produce a different body and a signature that does not
// verify.
const crypto = require('crypto');
const body = JSON.stringify($json);
const signature = crypto
  .createHmac('sha256', $env.DSNLAI_WEBHOOK_SECRET)
  .update(body)
  .digest('hex');
return [{ json: { body, signature } }];

// Reached only when the platform accepted the batch, so the history cursor
// never moves past mail the platform does not hold. A failed pass leaves it
// where it was and the next pass reads the same window again.
const history = $('Which part of the mailbox').all().find((item) => item.json.lane === 'history');
const state = $getWorkflowStaticData('global');
if (history) state.historyCursor = history.json.after;
return [{ json: { historyCursor: state.historyCursor ?? null, historyDone: !history } }];
